import math

def ndcg_at_k(recommended, relevant, k):
    dcg = 0.0
    for i, item in enumerate(recommended[:k]):
        if item in relevant:
            dcg += 1.0 / math.log2(i + 2)
    ideal = list(relevant)
    idcg = 0.0
    for i in range(min(len(ideal), k)):
        idcg += 1.0 / math.log2(i + 2)
    return round(dcg / idcg, 4) if idcg else 0.0

