def diversify_by_category(items, category_key, k, max_per_cat=2):
    result = []
    cat_count = {}
    for it in items:
        if len(result) >= k:
            break
        cat = it[category_key]
        if cat_count.get(cat, 0) >= max_per_cat:
            continue
        result.append(it)
        cat_count[cat] = cat_count.get(cat, 0) + 1
    return result

